/*
Proyecto: Gestión de Coworking
Grupo: 05
Módulo: Datos iniciales (DML)
Archivo: 01_datos_iniciales.sql
Descripción:
  Datos sintéticos coherentes para probar todo el sistema: 1 coworking,
  3 sedes, 16 espacios, 60 usuarios, 5 empresas, 465 suscripciones,
  529 reservas, 1349 consumos de servicios, 3005 registros de acceso,
  535 ventas, 531 facturas, 524 pagos, reportes, notificaciones y logs.
  Fecha de referencia ("hoy" de los datos): jueves 2026-10-01.
  Valores monetarios en dólares; IVA del 19 %.
  Incluye a propósito casos especiales para las consultas: dos pares de
  reservas solapadas (Q34), reservas que exceden la capacidad (Q28),
  pagos tardíos, pagos parciales, facturas anuladas, recargos, accesos
  con código inválido o fuera de horario, etc.
Requisitos:
  Ejecutar después de 00_ddl/01_estructura.sql (que ya inserta los
  métodos de pago) y ANTES de crear los triggers.
*/
